{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="Gentle, structure-first coaching to build habits that last. Cohort programs, practical frameworks, and a 7-day habit generator you can print." />
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body>
  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="index.html">
        <svg width="36" height="36" viewBox="0 0 100 100" aria-hidden="true">
          <rect width="100" height="100" rx="16" fill="#E6D7C2" />
          <circle cx="50" cy="40" r="18" fill="#C89A6B" />
          <rect x="28" y="62" width="44" height="10" rx="3" fill="#B76F46" />
        </svg>
        <span class="brand-text">{{BUSINESS_NAME}}</span>
      </a>
      <nav class="main-nav" aria-label="Primary">
        <a href="index.html">Root</a>
        <a href="about.html">Philosophy</a>
        <a href="services.html">Offerings</a>
        <a href="programs.html">Programs</a>
        <a href="pricing.html">Fees</a>
        <a href="testimonials.html">Voices</a>
        <a href="book.html">Schedule</a>
        <a href="contact.html">Contact</a>
      </nav>
      <div class="header-ctas">
        <a class="btn btn-outline" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        <button class="btn btn-primary" id="try-now-hero">Try it now</button>
      </div>
    </div>
  </header>

  <main>
    <!-- HERO -->
    <section class="hero" id="hero">
      <div class="wrap grid">
        <div class="col col-60">
          <h1>Design tiny rhythms that steady your days.</h1>
          <p class="lead">An approachable cohort that teaches simple frameworks to build repeatable wellbeing habits — without adding friction to busy lives.</p>
          <p class="meta">Live group weeks, concise toolkits, and a 7-day plan you can use right away.</p>
          <div class="hero-actions">
            <a class="btn btn-primary" href="{{PRIMARY_CTA_URL}}">Join the next cohort</a>
            <button class="btn" id="try-now-hero-2">Quick exercise</button>
            <button class="btn btn-outline" id="open-habit-builder">Build a 7-day plan</button>
          </div>
        </div>
        <div class="col col-40 hero-card" aria-hidden="true">
          <svg class="pattern" preserveAspectRatio="none" viewBox="0 0 200 200" xmlns="http://www.w3.org/2000/svg">
            <defs>
              <pattern id="p1" width="20" height="20" patternUnits="userSpaceOnUse">
                <rect width="20" height="20" fill="#F4EDE3" />
                <path d="M0 10 L10 0 L20 10" stroke="#E0C9AE" fill="none" stroke-width="1" />
              </pattern>
            </defs>
            <rect width="100%" height="100%" fill="url(#p1)" />
          </svg>
          <div class="card-content">
            <h3>Try a 5-minute grounding</h3>
            <p>Gentle prompts and a paced breath cycle — a fast reset you can do between meetings or before sleep.</p>
            <div class="card-actions">
              <button class="btn btn-primary" id="try-now-card">Try it now</button>
            </div>
          </div>
        </div>
      </div>
    </section>

    <!-- SOCIAL PROOF -->
    <section class="social-proof wrap" id="social-proof">
      <h2>Stories from cohort members</h2>
      <div class="testimonials grid">
        <blockquote>
          "I stopped trying to overhaul everything and instead practiced a single daily intention. The week felt manageable — and I kept going." <cite>— Asha, design lead</cite>
        </blockquote>
        <blockquote>
          "Group check-ins kept me honest in the kindest way. I found a 10-minute ritual that really shifted my weeks." <cite>— Marco, teacher</cite>
        </blockquote>
        <blockquote>
          "Practical checklists + a short coaching call = way more momentum than my previous plans." <cite>— Liana, entrepreneur</cite>
        </blockquote>
      </div>
    </section>

    <!-- BENEFITS -->
    <section class="benefits wrap" id="benefits">
      <h2>Outcomes we guide toward</h2>
      <div class="grid">
        <div class="col">
          <h3>Daily micro-routines</h3>
          <p>Short, repeatable actions that anchor your day — we teach how to slot them in so they stick.</p>
        </div>
        <div class="col">
          <h3>Group accountability</h3>
          <p>Cohorts, weekly check-ins, and shared trackers to maintain momentum without perfectionism.</p>
        </div>
        <div class="col">
          <h3>Frameworks, not fads</h3>
          <p>Simple habit maps and decision rules you can reuse for new goals and seasons.</p>
        </div>
      </div>
    </section>

    <!-- PROCESS (includes habit builder) -->
    <section class="process wrap" id="process">
      <h2>How a cohort unfolds</h2>
      <ol class="flow">
        <li><strong>Week 0:</strong> Orientation + pick a 7-day experiment.</li>
        <li><strong>Weeks 1–4:</strong> Two live group sessions per week, short focused exercises, and shared check-ins.</li>
        <li><strong>After:</strong> Reusable habit checklist and a repeatable cycle you can carry forward.</li>
      </ol>

      <div class="habit-builder" id="habit-builder">
        <h3>7-day challenge generator</h3>
        <p>Choose up to three micro-habits. Generate a printable 7-day checklist tailored to your goals.</p>
        <form id="habit-form">
          <label>Habit 1 <input name="habit1" placeholder="e.g., 2-minute breathwork" /></label>
          <label>Habit 2 <input name="habit2" placeholder="e.g., morning pages (5 min)" /></label>
          <label>Habit 3 <input name="habit3" placeholder="e.g., 10-minute walk" /></label>
          <div class="form-row">
            <label>Start day <select name="startDay">
              <option>Monday</option>
              <option>Tuesday</option>
              <option>Wednesday</option>
              <option>Thursday</option>
              <option>Friday</option>
              <option>Saturday</option>
              <option>Sunday</option>
            </select></label>
            <button class="btn btn-primary" id="generate-plan">Create checklist</button>
            <button type="button" class="btn" id="clear-plan">Reset</button>
          </div>
        </form>
        <div id="plan-output" aria-live="polite"></div>
      </div>
    </section>

    <!-- FAQ -->
    <section class="faq wrap" id="faq">
      <h2>Questions people ask</h2>
      <details>
        <summary>What will I actually do in a week?</summary>
        <p>You pick a short, focused set of practices (2–3) and use our decision map to slot them into existing moments. Live sessions introduce frameworks and provide gentle accountability.</p>
      </details>
      <details>
        <summary>Is this a medical program?</summary>
        <p>No — the focus is habit frameworks, simple practices, and community. We do not provide medical advice.</p>
      </details>
      <details>
        <summary>How much time will it take?</summary>
        <p>Most materials and exercises are 5–15 minutes daily. Live calls are positioned to be efficient and practical.</p>
      </details>
    </section>

    <!-- CTA -->
    <section class="cta wrap" id="final-cta">
      <h2>Ready to join a focused week?</h2>
      <p>Small structures, clear prompts, and cohort rhythm — enroll to begin the next cycle.</p>
      <div class="cta-actions">
        <a class="btn btn-primary" href="{{PRIMARY_CTA_URL}}">Reserve a spot</a>
        <a class="btn btn-outline" href="contact.html">Ask a question</a>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div class="wrap">
      <div class="foot-left">
        <strong>{{BUSINESS_NAME}}</strong>
        <address>{{CITY}}, {{STATE}} • <a href="tel:{{PHONE}}">{{PHONE}}</a> • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></address>
      </div>
      <div class="foot-right">
        <nav>
          <a href="about.html">About</a>
          <a href="programs.html">Programs</a>
          <a href="book.html">Book</a>
        </nav>
      </div>
    </div>
  </footer>

  <!-- Guided exercise modal -->
  <div class="modal" id="exercise-modal" aria-hidden="true" role="dialog" aria-modal="true">
    <div class="modal-panel">
      <button class="modal-close" id="exercise-close" aria-label="Close">×</button>
      <h3 id="exercise-title">Quick Reset</h3>
      <div class="exercise-tabs">
        <button data-mode="breathing" class="tab active">Breathing</button>
        <button data-mode="journaling" class="tab">Journaling</button>
        <button data-mode="intention" class="tab">Intention</button>
      </div>
      <div class="exercise-body" id="exercise-body">
        <!-- Populated by JS -->
      </div>
      <div class="exercise-controls">
        <button class="btn" id="exercise-start">Start</button>
        <button class="btn btn-outline" id="exercise-skip">Skip</button>
      </div>
    </div>
  </div>

  <!-- Habit printable modal -->
  <div class="modal" id="print-modal" aria-hidden="true">
    <div class="modal-panel">
      <button class="modal-close" id="print-close" aria-label="Close">×</button>
      <h3>Your 7-day checklist</h3>
      <div id="print-preview"></div>
      <div class="exercise-controls">
        <button class="btn btn-primary" id="print-to-printer">Print</button>
        <button class="btn" id="download-pdf">Download (PDF-friendly)</button>
      </div>
    </div>
  </div>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
